package connect

// neighbors are the six directions a hexagonal field can connect to,
// expressed as (row, col) offsets in the board grid. The board is a
// parallelogram: each row is sheared one cell to the right, so the six
// neighbours of a cell are these symmetric offsets.
var neighbors = [6][2]int{
	{-1, 0}, {-1, 1},
	{0, -1}, {0, 1},
	{1, -1}, {1, 0},
}

// ResultOf computes the winner of a game of Hex / Polygon.
// Player "X" connects the left side to the right side; player "O"
// connects the top side to the bottom side. It returns "X", "O", or ""
// when no player has made a connection.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	height := len(lines)
	width := len(lines[0])

	// X connects the left side to the right side.
	if connects(lines, 'X', height, width, true) {
		return "X", nil
	}

	// O connects the top side to the bottom side.
	if connects(lines, 'O', height, width, false) {
		return "O", nil
	}

	return "", nil
}

// connects reports whether the given player has a chain of stones linking
// their two assigned sides. When horizontal is true the sides are the left
// and right columns; otherwise they are the top and bottom rows.
func connects(lines []string, player rune, height, width int, horizontal bool) bool {
	visited := make([][]bool, height)
	for i := range visited {
		visited[i] = make([]bool, width)
	}

	stack := make([][2]int, 0)
	for r := 0; r < height; r++ {
		for c := 0; c < width; c++ {
			if lines[r][c] != byte(player) {
				continue
			}
			onStart := horizontal ? c == 0 : r == 0
			if !onStart {
				continue
			}
			visited[r][c] = true
			stack = append(stack, [2]int{r, c})
		}
	}

	for len(stack) > 0 {
		cell := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		r, c := cell[0], cell[1]

		onEnd := horizontal ? c == width-1 : r == height-1
		if onEnd {
			return true
		}

		for _, n := range neighbors {
			nr, nc := r+n[0], c+n[1]
			if nr < 0 || nr >= height || nc < 0 || nc >= width {
				continue
			}
			if visited[nr][nc] || lines[nr][nc] != byte(player) {
				continue
			}
			visited[nr][nc] = true
			stack = append(stack, [2]int{nr, nc})
		}
	}

	return false
}

